const recordVoiceInputBoundary = `-- name: RecordVoiceInputBoundary :exec
WITH previous_input AS (
  SELECT id,last_input_started_ms,last_input_ended_ms
  FROM voice_sessions
  WHERE id=$3::text
  FOR NO KEY UPDATE
), interrupted_capture AS (
  UPDATE capture_sessions capture
  SET transcript_integrity_lost=true
  FROM previous_input previous
  WHERE capture.voice_session_id=previous.id
    AND capture.status IN ('starting','recording','finalizing')
    AND $1::text='track_started'
    AND $2::bigint > coalesce(previous.last_input_started_ms,-1)
    AND previous.last_input_started_ms IS NOT NULL
    AND (
      previous.last_input_started_ms > coalesce(previous.last_input_ended_ms,-1) OR
      $2::bigint > greatest(coalesce(previous.last_input_ended_ms,$2::bigint),
        coalesce(capture.transcript_start_offset_ms,$2::bigint)) + 250
    )
  RETURNING capture.id,
    greatest(coalesce(capture.transcript_start_offset_ms,0),
      CASE WHEN previous.last_input_started_ms > coalesce(previous.last_input_ended_ms,-1)
      THEN coalesce((SELECT max(coverage.end_offset_ms) FROM capture_transcript_coverage coverage
        WHERE coverage.session_id=capture.id AND coverage.end_offset_ms<=$2::bigint),previous.last_input_started_ms)
      ELSE previous.last_input_ended_ms END) AS uncertainty_start
), uncertainty AS (
  INSERT INTO voice_transcript_uncertainties(capture_session_id,event_id,start_offset_ms,end_offset_ms,reason)
  SELECT id,'track-start:' || $2::bigint::text,uncertainty_start,$2::bigint,'track_interruption'
  FROM interrupted_capture WHERE uncertainty_start<$2::bigint
  ON CONFLICT(capture_session_id,event_id) DO NOTHING
)
UPDATE voice_sessions voice
SET last_input_started_ms=CASE WHEN $1::text='track_started'
      THEN greatest(coalesce(voice.last_input_started_ms,0),$2::bigint) ELSE voice.last_input_started_ms END,
    last_input_ended_ms=CASE WHEN $1::text='track_ended'
      THEN greatest(coalesce(voice.last_input_ended_ms,0),$2::bigint) ELSE voice.last_input_ended_ms END
FROM previous_input previous
WHERE voice.id=previous.id
`

type RecordVoiceInputBoundaryParams struct {
	Kind           string `json:"kind"`
	OffsetMs       int64  `json:"offset_ms"`
	VoiceSessionID string `json:"voice_session_id"`
}

func (q *Queries) RecordVoiceInputBoundary(ctx context.Context, arg RecordVoiceInputBoundaryParams) error {
	_, err := q.db.Exec(ctx, recordVoiceInputBoundary, arg.Kind, arg.OffsetMs, arg.VoiceSessionID)
	return err
}

