const voiceSessionReconcileDueIn = `-- name: VoiceSessionReconcileDueIn :one
SELECT coalesce(extract(epoch FROM min(updated_at+CASE
    WHEN last_failure_code='publisher_absent' AND status<>'closing' THEN interval '60 seconds'
    ELSE $1::interval
  END)-clock_timestamp()),'Infinity')::float8 AS wait_seconds
FROM voice_sessions
WHERE id=$2::text AND status IN ('provisioning','connected','reconnecting','closing')
`

type VoiceSessionReconcileDueInParams struct {
	MinAge pgtype.Interval `json:"min_age"`
	ID     string          `json:"id"`
}

// Seconds until ClaimVoiceSessionReconcile can take the session; Infinity
// once it is closed.
func (q *Queries) VoiceSessionReconcileDueIn(ctx context.Context, arg VoiceSessionReconcileDueInParams) (float64, error) {
	row := q.db.QueryRow(ctx, voiceSessionReconcileDueIn, arg.MinAge, arg.ID)
	var wait_seconds float64
	err := row.Scan(&wait_seconds)
	return wait_seconds, err
}

const voiceStagingCleanupReady = `-- name: VoiceStagingCleanupReady :one
SELECT EXISTS (
  SELECT 1 FROM capture_sessions capture
  WHERE capture.id=$1 AND capture.status IN ('finalized','failed') AND capture.staging_deleted_at IS NULL
    AND NOT EXISTS (SELECT 1 FROM voice_media_epochs epoch WHERE epoch.capture_session_id=capture.id
      AND epoch.observed_state IN ('requested','active','sealing','unknown'))
)::boolean AS ready
`

// Reports whether the Capture ended and no recorder can still write its
// staging; a Capture whose staging is already gone is not ready.
func (q *Queries) VoiceStagingCleanupReady(ctx context.Context, id string) (bool, error) {
	row := q.db.QueryRow(ctx, voiceStagingCleanupReady, id)
	var ready bool
	err := row.Scan(&ready)
	return ready, err
}
